///  Options for a propagation.
class tbpPropagationRequest {
  tbpPropagationRequest._(this._bc, this._bcOffset);
  factory tbpPropagationRequest(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<tbpPropagationRequest> reader = _tbpPropagationRequestReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  tbpState? get INITIAL_STATE => tbpState.reader.vTableGetNullable(_bc, _bcOffset, 4);
  tbpState? get initialState => INITIAL_STATE;
  ///  Non-dimensional duration (negative = backwards).
  double get DURATION => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 6, 0.0);
  ///  Non-dimensional integration step; 0 = default.
  double get STEP => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 8, 0.0);
  ///  Samples in the answer, endpoints included; 0 = default.
  int get OUTPUT_POINTS => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 10, 0);
  int get outputPoints => OUTPUT_POINTS;
  ///  Also propagate the state transition matrix.
  bool get STATE_TRANSITION => const fb.BoolReader().vTableGet(_bc, _bcOffset, 12, false);
  bool get stateTransition => STATE_TRANSITION;

  @override
  String toString() {
    return 'tbpPropagationRequest{initialState: ${initialState}, DURATION: ${DURATION}, STEP: ${STEP}, outputPoints: ${outputPoints}, stateTransition: ${stateTransition}}';
  }
}

